//! Cross-crate protocol parser.
/// Returns the unconsumed payload after a valid marker.
pub fn recognize(input: &[u8]) -> Option<&[u8]> {
    prefix_core::consume(input, b"LYNX")
}
/// Exercises the array-pattern implementation without a slice coercion.
pub fn array(input: &[u8]) -> Option<&[u8]> {
    prefix_core::consume_array(input)
}

